-- Generated by matugen from ~/.config/matugen/templates/nvim-colors.lua — edit the template, not this file.
local c = {
  bg = "#191113",
  bg1 = "#261d1f",
  bg2 = "#3c3234",
  outline = "#9f8c8f",
  outline_v = "#524345",
  fg_dim = "#d6c2c4",
  fg = "#efdee0",
  primary = "#ffb1c1",
  on_primary = "#551d2c",
  primary_c = "#713342",
  on_primary_c = "#ffd9df",
  secondary = "#e4bdc3",
  tertiary = "#ecbe91",
  on_tertiary_c = "#ffdcbc",
  error = "#ffb4ab",
  green = "#a8d292",
  yellow = "#ffb782",
}

vim.o.background = "dark"
require("base16-colorscheme").setup({
  base00 = c.bg, base01 = c.bg1, base02 = c.bg2, base03 = c.outline,
  base04 = c.fg_dim, base05 = c.fg, base06 = c.fg, base07 = c.fg,
  base08 = c.error, base09 = c.yellow, base0A = c.tertiary, base0B = c.green,
  base0C = c.on_primary_c, base0D = c.primary, base0E = c.secondary, base0F = c.on_tertiary_c,
})
vim.g.colors_name = "matugen"

local hl = function(name, opts) vim.api.nvim_set_hl(0, name, opts) end
hl("Comment", { fg = c.outline, italic = true })
hl("@comment", { link = "Comment" })
hl("Keyword", { fg = c.secondary, bold = true })
hl("@keyword", { link = "Keyword" })
hl("Function", { fg = c.primary, bold = true })
hl("@function", { link = "Function" })
hl("String", { fg = c.green, italic = true })
hl("@string", { link = "String" })
hl("Type", { fg = c.tertiary, italic = true })
hl("@type", { link = "Type" })
hl("CursorLine", { bg = c.bg1 })
hl("CursorLineNr", { fg = c.primary, bold = true })
hl("LineNr", { fg = c.outline_v })
hl("Visual", { bg = c.primary_c, fg = c.on_primary_c })
hl("NormalFloat", { bg = c.bg1, fg = c.fg })
hl("FloatBorder", { bg = c.bg1, fg = c.primary })
hl("FloatTitle", { bg = c.primary, fg = c.on_primary, bold = true })
hl("WinSeparator", { fg = c.outline_v })
hl("Pmenu", { bg = c.bg1, fg = c.fg })
hl("PmenuSel", { bg = c.primary_c, fg = c.on_primary_c, bold = true })
hl("MatchParen", { bg = c.bg2, fg = c.primary, bold = true })
hl("Search", { bg = c.primary_c, fg = c.on_primary_c })
hl("IncSearch", { bg = c.primary, fg = c.on_primary })
-- markdown headings: primary → tertiary ramp
for i, col in ipairs({ c.primary, c.secondary, c.tertiary, c.green, c.yellow, c.fg_dim }) do
  hl("@markup.heading." .. i .. ".markdown", { fg = col, bold = true })
  hl("RenderMarkdownH" .. i, { fg = col, bold = true })
  hl("RenderMarkdownH" .. i .. "Bg", { bg = c.bg1, fg = col })
end
hl("RenderMarkdownCode", { bg = c.bg1 })
hl("@markup.link", { fg = c.primary, underline = true })
hl("@markup.raw", { fg = c.tertiary })
